path = "app/views/pwa/service_worker.js.erb"
src = File.read(path)
old = "self.addEventListener(\"activate\", (event) => {\n  event.waitUntil(self.clients.claim())\n})\n"
new = old + <<'JS'

// Push notifications: show what the tray says, and open the card when it's tapped
self.addEventListener("push", (event) => {
  const { title, body, tag, url } = event.data.json()

  event.waitUntil(self.registration.showNotification(title, {
    body,
    tag,
    renotify: true,
    icon: "/app-icon-192.png",
    data: { url }
  }))
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()
  event.waitUntil(openNotificationUrl(event.notification.data.url))
})

async function openNotificationUrl(url) {
  const [ client ] = await self.clients.matchAll({ type: "window", includeUncontrolled: true })

  if (client?.navigate) {
    await client.focus()
    return client.navigate(url)
  } else {
    return self.clients.openWindow(url)
  }
}
