            openWindow: async (url) => { calls.opened.push(url) },
            claim: async () => {}
          }
        }
        const TurboOffline = { addRule() {}, handlers: { networkFirst() {}, cacheFirst() {} }, start() {} }
        new Function("self", "TurboOffline", "importScripts", source)(self, TurboOffline, () => {})

        const pending = []
        const waitUntil = (p) => pending.push(p)

        listeners.push({ data: { json: () => ({ title: "RE: Layout is broken", body: "Looks wrong", tag: "notification-1", url: "http://127.0.0.1/x/cards/2#comment_1" }) }, waitUntil })
